type **pointer_name; // Pointer to a pointer
// Using pointer arithmetic for traversal or modification
pointer_name = &some_pointer;
*pointer_name = new_value; // Modifying the data via double indirection
// Creating aliasing relationships to manipulate linked nodes efficiently

code_example:
typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *head = NULL;
Node **pp = &head; // Pointer to the head pointer for flexible insertion

// Insert a new node at the beginning using pointer-to-pointer
Node *new_node = malloc(sizeof(Node));
new_node->value = 42;
new_node->next = *pp;
*pp = new_node; // head now points to new_node

// Traversal using pointer-to-pointer to delete nodes with specific value
pp = &head;
while (*pp) {
    if ((*pp)->value == 42) {
        Node *temp = *pp;
        *pp = (*pp)->next; // Bypass the node to delete
        free(temp);
    } else {
        pp = &(*pp)->next;
    }
}
